from decimal import Decimal, ROUND_HALF_UP
CENT = Decimal('0.01')
VAT = Decimal('0.16')
def vat_per_line(prices):
    return sum((p * VAT).quantize(CENT, rounding=ROUND_HALF_UP) for p in prices)
def vat_on_total(prices):
    return (sum(prices) * VAT).quantize(CENT, rounding=ROUND_HALF_UP)
basket = [Decimal('0.53'), Decimal('0.53'), Decimal('0.53')]
print(vat_per_line(basket))
print(vat_on_total(basket))

from decimal import Decimal
def additive(price, discounts):
    return price * (1 - sum(discounts))
print(additive(Decimal('100'), [Decimal('0.10'), Decimal('0.20')]))

def parse_rule(rule):
    match rule.split(':'):
        case ['pct', value]:
            return ('pct', float(value))
        case ['fixed', value]:
            return ('fixed', int(value))
        case _:
            return ('unknown', rule)
print(parse_rule('pct:10'))
print(parse_rule('fixed:250'))

